  /** Idea registry stats: source_count distribution, singly-linked, backbone, dormant.
   *  Optional opts: { offset?, limit?, tier? } — paginates the singletons (the largest
   *  bucket and the only one a hygiene workflow needs to walk through systematically).
   *  Default offset=0, limit=20, tier='singleton'. backbone + dormant are caps still.
   *
   *  tier values:
   *    - 'singleton' (default) — sourceCount <= 1
   *    - 'doubly'              — sourceCount === 2
   *    - 'thrice'              — sourceCount === 3 (rarely useful, but available)
   *
   *  Returns the requested page in `singlyLinked.ideas[]` (or doubly.ideas, thrice.ideas
   *  per tier choice) — total count remains the full bucket size so caller knows when
   *  to stop paging. Sync. */
  torusIdeaStats(optsJson) {
    const t02 = performance.now();
    let opts = {};
    if (optsJson) {
      try {
        opts = JSON.parse(optsJson);
      } catch {
      }
    }
    const offset = Math.max(0, Math.floor(opts.offset ?? 0));
    const limit = Math.max(1, Math.floor(opts.limit ?? 20));
    const tier = opts.tier || "singleton";
    const ideasDir = this.settings.ideasDir;
    const ideaFiles = this.app.vault.getMarkdownFiles().filter((f) => f.path.startsWith(ideasDir + "/"));
    const ideas = [];
    for (const f of ideaFiles) {
      const cache3 = this.app.metadataCache.getFileCache(f);
      const sc = cache3?.frontmatter?.torus_refs;
      ideas.push({
        name: f.basename,
        path: f.path,
        sourceCount: typeof sc === "number" ? sc : 0,
        lastModified: new Date(f.stat.mtime).toISOString().slice(0, 10)
      });
    }
    const total = ideas.length;
    const singlyLinked = ideas.filter((i3) => i3.sourceCount <= 1).sort((a2, b2) => a2.path.localeCompare(b2.path));
    const doubly = ideas.filter((i3) => i3.sourceCount === 2).sort((a2, b2) => a2.path.localeCompare(b2.path));
    const thrice = ideas.filter((i3) => i3.sourceCount === 3).sort((a2, b2) => a2.path.localeCompare(b2.path));
    const backbone = ideas.filter((i3) => i3.sourceCount >= 6).sort((a2, b2) => b2.sourceCount - a2.sourceCount);
    const twoWeeksAgo = new Date(Date.now() - 14 * 864e5).toISOString().slice(0, 10);
    const dormant = ideas.filter((i3) => i3.lastModified < twoWeeksAgo && i3.sourceCount > 0).sort((a2, b2) => b2.sourceCount - a2.sourceCount);
    const page = (arr) => arr.slice(offset, offset + limit).map((i3) => ({ name: i3.name, path: i3.path, sourceCount: i3.sourceCount }));
    const tierBuckets = {
      singletons: { count: singlyLinked.length, ideas: tier === "singleton" ? page(singlyLinked) : [] },
      doubly: { count: doubly.length, ideas: tier === "doubly" ? page(doubly) : [] },
      thrice: { count: thrice.length, ideas: tier === "thrice" ? page(thrice) : [] }
    };
    this.torusTrace(`plugin:torusIdeaStats`, `${Math.round(performance.now() - t02)}ms ideas=${total} tier=${tier} offset=${offset} limit=${limit}`);
    return JSON.stringify({
      total,
      tier,
      offset,
      limit,
      // Backwards-compat: keep singlyLinked at top-level (skills referencing it still work).
      // It mirrors tierBuckets.singletons unless tier is explicitly 'doubly' or 'thrice'.
      singlyLinked: tierBuckets.singletons,
      doubly: tierBuckets.doubly,
      thrice: tierBuckets.thrice,
      backbone: backbone.slice(0, 15).map((i3) => ({ name: i3.name, path: i3.path, sourceCount: i3.sourceCount })),
      dormant: { count: dormant.length, ideas: dormant.slice(0, 15).map((i3) => ({ name: i3.name, path: i3.path, sourceCount: i3.sourceCount, lastModified: i3.lastModified })) }
    });
  }
